#: The office profiles a name can be read from, in the order they are tried.
PROFILE_MODELS = (
    'PrincipalProfile', 'HeadOfDepartmentProfile', 'AccountantProfile', 'SecretaryProfile',
    'RecordsOfficerProfile', 'AdmissionOfficerProfile', 'EstateOfficerProfile', 'TeacherProfile',
)


def _name_for(apps, user):
    for name in PROFILE_MODELS:
        row = apps.get_model('attendance', name).objects.filter(user=user).first()
        if row and row.full_name:
            return row.full_name
    return (f'{user.first_name} {user.last_name}'.strip()) or user.username


def exam_office_gets_its_own_role(apps, schema_editor):
    """The examination officer used to be "an admin account that is neither
    Principal nor Head of Department". Each such account is given the office
    by name before the flag stops meaning anything, so nobody signs in on the
    day after the deploy to find their work gone.

    Then `is_staff` is taken off everyone except superusers: from here on it
    means only "may open Django's own admin site", which the ICT officer's role
    sets. A superuser keeps it, as the sealed account kept for emergencies.
    """
    User = apps.get_model(*settings.AUTH_USER_MODEL.split('.'))
    Principal = apps.get_model('attendance', 'PrincipalProfile')
    Hod = apps.get_model('attendance', 'HeadOfDepartmentProfile')
    ExamOfficer = apps.get_model('attendance', 'ExamOfficerProfile')
    for user in User.objects.filter(is_staff=True):
        office = (Principal.objects.filter(user=user, is_active=True).exists()
                  or Hod.objects.filter(user=user, is_active=True).exists())
        if not office:
            ExamOfficer.objects.get_or_create(user=user, defaults={'full_name': _name_for(apps, user)})
    User.objects.filter(is_staff=True, is_superuser=False).update(is_staff=False)


def admin_flag_back(apps, schema_editor):
    """Going back: the offices that carried `is_staff` carry it again."""
    User = apps.get_model(*settings.AUTH_USER_MODEL.split('.'))
    ids = set()
    for name in ('PrincipalProfile', 'HeadOfDepartmentProfile', 'ExamOfficerProfile'):
        ids |= set(apps.get_model('attendance', name).objects.filter(
            is_active=True).values_list('user_id', flat=True))
    User.objects.filter(id__in=ids).update(is_staff=True)


